ALTER POLICY tenant_isolation ON public.tasks USING (organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid() AND owner_id=current_setting('app.user_id',true) AND coalesce(data->>'authorizationVersion',current_setting('app.authorization_version',true))=current_setting('app.authorization_version',true) AND (department_id IS NULL OR current_setting('app.all_departments',true)='true' OR department_id=ANY(string_to_array(current_setting('app.department_ids',true),',')))) WITH CHECK (organization_id=nullif(current_setting('app.organization_id',true),'') AND birdview_private.context_is_valid() AND owner_id=current_setting('app.user_id',true) AND coalesce(data->>'authorizationVersion',current_setting('app.authorization_version',true))=current_setting('app.authorization_version',true) AND (department_id IS NULL OR current_setting('app.all_departments',true)='true' OR department_id=ANY(string_to_array(current_setting('app.department_ids',true),','))));
